import os, re
SP = os.path.dirname(os.path.abspath(__file__))
def rd(p): return open(p, encoding='utf-8').read()
def R(pat, text, name, flags=0):
    g = re.search(pat, text, flags); assert g, (name, pat[:60]); return g.groups() if g.re.groups > 1 else g.group(1)
def text(S):
    c = S.counts(); RC = rd(f'{SP}/ch33b_recon.out'); ER = rd(f'{SP}/ch33_exam_rows.out'); CL = rd(f'{SP}/ch33_callees.out')
    RUN = R(r"RUN = \((\d+), (\d+), (\d+), (\d+), (\d+), (\d+), (\d+), (\d+),", RC, 'RUN'); PL = R(r"PLACEMENT = (\{'markers'.*?\}\})", RC, 'PLACEMENT')
    IMP, DO = R(r"import lines: (\d+) \| DAEMON_ORDER tuples: (\d+)", RC, 'imports'); CPS, DS, LASTCP = R(r"checkpoints: (\d+) \| the D series in use: (\[.*?\]) \| last: (\w+)", RC, 'cps')
